## Step 8: Write the Certification Test

The certification test runs at Studio import time. It must pass for the package to be importable.

```typescript
// tests/member-member-search.cert.ts
import { certify } from '@portal-studio/certify';
import manifest from '../studio-manifest.json';

const module = manifest.modules.find(m => m.namespace === '@member/member-search')!;

certify(module.namespace, {
  remoteEntry: module.remoteEntry,
  exposedModule: module.exposedModule,
  contract: module.contract,
  checks: {
    bundleSize: true,          // ≤ 500 KB gzipped (shared React excluded)
    remoteLoadable: true,      // remoteEntry.js resolves and exposedModule is accessible
    contractCompleteness: true,
    contentSlotDefaults: true,
    styleHooksSupportable: true,
    wcagAA: true,
    keyboardNavigation: true,
  },
});
```

Run locally before publishing:
```bash
npx ts-node tests/member-member-search.cert.ts
```

